mapper.select:
SELECT DATE(DATE_ADD(started_at, INTERVAL 9 HOUR)) AS day
FROM score_views
WHERE user_id = #{userId} AND started_at < #{to}
GROUP BY day
HAVING SUM(counted_seconds) >= #{minSeconds}
ORDER BY day DESC

SELECT ps.id AS session_id, ps.started_at, ps.bpm, ps.bpm_unit, ps.start_note_idx, ps.end_note_idx, ps.score_version,
       e.model_version, e.total_score, e.pitch_score, e.timing_score, e.duration_score

  AND ps.song_id = #{songId}
  AND NOT 
ORDER BY ps.started_at DESC, ps.id DESC
LIMIT #{limit}

SELECT 

  AND ps.song_id = #{songId} AND ps.score_version = #{scoreVersion} AND e.model_version = #{modelVersion}
  AND ps.bpm = #{bpm} AND ps.bpm_unit = #{bpmUnit}
ORDER BY ps.started_at ASC, ps.id ASC
LIMIT 1
